        }
    }
    pub fn as_str(&self) -> Option<&str> {
        match self {
            Yaml::String(s) => Some(s),
            _ => None,
        }
    }
    pub fn as_hash(&self) -> Option<&Vec<(Yaml, Yaml)>> {
        match self {
            Yaml::Hash(pairs) => Some(pairs),
            _ => None,
        }
    }
    pub fn is_bad_value(&self) -> bool {
        matches!(self, Yaml::BadValue)
    }
}

#[derive(Clone)]
pub struct ScanError {
    pub index: usize,
    pub line: usize,
    pub col: usize,
    pub info: String,
}

impl fmt::Debug for ScanError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "ScanError {{ mark: Marker {{ index: {}, line: {}, col: {} }}, info: {:?} }}",
            self.index, self.line, self.col, self.info
        )
    }
}

struct Line {
    indent: usize,
    content: String,
    no: usize,
    char_index: usize,
}

pub fn load_from_str(input: &str) -> Result<Vec<Yaml>, ScanError> {
    // Split into documents at lines starting a new document.
    let mut docs: Vec<Vec<String>> = Vec::new();
    let mut cur: Vec<String> = Vec::new();
    let mut cur_started = false;
    let mut saw_separator = false;
    for raw in input.lines() {
        let trimmed = raw.trim();
        if trimmed == "---" || trimmed.starts_with("--- ") {
            if cur_started || saw_separator || !cur.is_empty() {
                docs.push(cur);
                cur = Vec::new();
            }
            saw_separator = true;
            cur_started = true;
            let rest = if trimmed.len() > 3 { trimmed[3..].trim().to_string() } else { String::new() };
            if !rest.is_empty() {
                cur.push(rest);
            }
            continue;
        }
        if trimmed == "..." {
            docs.push(cur);
            cur = Vec::new();
            cur_started = false;
            continue;
        }
        cur_started = true;
        cur.push(raw.to_string());
    }
    if cur_started || !cur.is_empty() {
        docs.push(cur);
    }
    let mut out = Vec::new();
    for doc in docs {
        let text: Vec<String> = doc;
        let joined = text.join("\n");
        if joined.trim().is_empty() {
            // A wholly empty document.  `YamlLoader` returns no document for
            // empty/comment-only input, but returns Null for a bare `---`.
            if saw_separator && input.trim_start().starts_with("---") {
                out.push(Yaml::Null);
            }
            continue;
        }
        let mut parser = Parser::new(&text);
        let v = parser.parse_document()?;
        out.push(v);
    }
    Ok(out)
}

struct Parser {
    lines: Vec<Line>,
    pos: usize,
}

fn strip_comment(s: &str) -> String {
    let mut in_single = false;
    let mut in_double = false;
    let mut escaped = false;
    let chars: Vec<char> = s.chars().collect();
    for i in 0..chars.len() {
        let c = chars[i];
        if in_double {
            if escaped {
                escaped = false;
            } else if c == '\\' {
                escaped = true;
            } else if c == '"' {
                in_double = false;
            }
            continue;
        }
        if in_single {
            if c == '\'' {
                in_single = false;
            }
            continue;
        }
        match c {
            '"' => in_double = true,
            '\'' => in_single = true,
            '#' => {
                if i == 0 || chars[i - 1].is_whitespace() {
                    return chars[..i].iter().collect::<String>().trim_end().to_string();
                }
            }
            _ => {}
        }
    }
    s.trim_end().to_string()
}

impl Parser {
    fn new(raw_lines: &[String]) -> Self {
        let mut lines = Vec::new();
        let mut char_index = 0usize;
        for (i, raw0) in raw_lines.iter().enumerate() {
            let raw = raw0.strip_suffix('\r').unwrap_or(raw0);
            char_index += raw.chars().count() + 1;
            let no_comment = strip_comment(raw);
            if no_comment.trim().is_empty() {
                continue;
            }
            let indent = no_comment.chars().take_while(|c| *c == ' ' || *c == '\t').map(|c| if c == '\t' { 1 } else { 1 }).count();
            let content = no_comment.trim_start().to_string();
            lines.push(Line { indent, content, no: i + 1, char_index });
        }
        Parser { lines, pos: 0 }
    }

    fn err(&self, info: &str) -> ScanError {
        let (line, col, index) = if self.pos < self.lines.len() {
            let l = &self.lines[self.pos];
            (l.no, l.indent + 1, l.char_index)
        } else if let Some(l) = self.lines.last() {
            (l.no + 1, 0, l.char_index)
        } else {
            (1, 0, 0)
        };
        ScanError { index, line, col, info: info.to_string() }
    }

    fn parse_document(&mut self) -> Result<Yaml, ScanError> {
        if self.lines.is_empty() {
            return Ok(Yaml::Null);
        }
        let indent = self.lines[0].indent;
        let v = self.parse_node(indent)?;
        if self.pos < self.lines.len() {
            return Err(self.err("did not find expected <document start>"));
        }
        Ok(v)
    }

    fn peek(&self) -> Option<&Line> {
        self.lines.get(self.pos)
    }

    fn parse_node(&mut self, min_indent: usize) -> Result<Yaml, ScanError> {
        let line = match self.peek() {
            Some(l) => l,
            None => return Ok(Yaml::Null),
        };
        if line.indent < min_indent {
            return Ok(Yaml::Null);
        }
        let indent = line.indent;
        let content = line.content.clone();
        if content == "-" || content.starts_with("- ") {
            return self.parse_sequence(indent);
        }
        if find_mapping_colon(&content).is_some() {
            return self.parse_mapping(indent);
        }
        // Plain / quoted scalar occupying a single line (multi-line plain
        // scalars are not needed for theme files; consume only this line).
        self.pos += 1;
        Ok(parse_scalar_token(&content))
    }

    fn parse_sequence(&mut self, indent: usize) -> Result<Yaml, ScanError> {
        let mut items = Vec::new();
        while let Some(line) = self.peek() {
            if line.indent != indent {
                break;
            }
            let content = line.content.clone();
            if !(content == "-" || content.starts_with("- ")) {
                break;
            }
            let after = if content.len() > 1 { content[1..].trim_start().to_string() } else { String::new() };
            let no = line.no;
            let _ = no;
            self.pos += 1;
            if after.is_empty() {
                // Nested block on following lines, or Null.
                match self.peek() {
                    Some(n) if n.indent > indent => {
                        let ni = n.indent;
                        items.push(self.parse_node(ni)?);
                    }
                    _ => items.push(Yaml::Null),
                }
            } else if find_mapping_colon(&after).is_some() || after == "-" || after.starts_with("- ") {
                // A compact block starting on the dash line.  Re-insert it
                // as a synthetic line with deeper indentation.
                let synthetic = Line { indent: indent + 2, content: after.clone(), no: line.no, char_index: line.char_index };
                self.lines.insert(self.pos, synthetic);
                items.push(self.parse_node(indent + 2)?);
            } else {
                items.push(parse_inline(&after).map_err(|e| self.err(&e))?);
            }
        }
        Ok(Yaml::Array(items))
    }

    fn parse_mapping(&mut self, indent: usize) -> Result<Yaml, ScanError> {
        let mut pairs: Vec<(Yaml, Yaml)> = Vec::new();
        while let Some(line) = self.peek() {
            if line.indent != indent {
                break;
            }
            let content = line.content.clone();
            let colon = match find_mapping_colon(&content) {
                Some(c) => c,
                None => break,
            };
            // colon is a byte index of ':' in content.
            let key_str = content[..colon].trim().to_string();
            let key = parse_scalar_token(&key_str);
            let rest = content[colon + 1..].trim_start().to_string();
            self.pos += 1;
            let value: Yaml;
            if !rest.is_empty() {
                value = parse_inline(&rest).map_err(|e| self.err(&e))?;
            } else {
                match self.peek() {
                    Some(n) if n.indent > indent => {
                        let ni = n.indent;
                        value = self.parse_node(ni)?;
                    }
                    Some(n) if n.indent == indent && (n.content == "-" || n.content.starts_with("- ")) => {
                        value = self.parse_sequence(indent)?;
                    }
                    _ => value = Yaml::Null,
                }
            }
            // Insert or replace, preserving first position.
            let mut replaced = false;
            for pair in pairs.iter_mut() {
                if pair.0 == key {
                    pair.1 = value.clone();
                    replaced = true;
                    break;
                }
            }
            if !replaced {
                pairs.push((key, value));
            }
        }
        Ok(Yaml::Hash(pairs))
    }
}

fn find_mapping_colon(content: &str) -> Option<usize> {
    let bytes = content.as_bytes();
    let mut in_single = false;
    let mut in_double = false;
    let mut escaped = false;
    let mut depth_flow = 0i32;
    let mut i = 0usize;
    while i < bytes.len() {
        let c = bytes[i] as char;
        if in_double {
            if escaped { escaped = false; } else if c == '\\' { escaped = true; } else if c == '"' { in_double = false; }
            i += 1;
            continue;
        }
        if in_single {
            if c == '\'' { in_single = false; }
            i += 1;
            continue;
        }
        match c {
            '"' => in_double = true,
            '\'' => in_single = true,
            '{' | '[' => depth_flow += 1,
            '}' | ']' => depth_flow -= 1,
            ':' if depth_flow == 0 => {
                if i + 1 >= bytes.len() || bytes[i + 1] == b' ' || bytes[i + 1] == b'\t' {
                    return Some(i);
                }
            }
            _ => {}
        }
        i += 1;
    }
    None
}

fn parse_inline(token: &str) -> Result<Yaml, String> {
    let t = token.trim();
    if t.is_empty() {
        return Ok(Yaml::Null);
    }
    if t.starts_with('{') {
        if !t.ends_with('}') {
            return Err("while parsing a flow mapping, expected ',' or '}'".to_string());
        }
        let inner = &t[1..t.len() - 1];
        let mut pairs: Vec<(Yaml, Yaml)> = Vec::new();
        if !inner.trim().is_empty() {
            for part in split_flow(inner) {
                let part = part.trim();
                let colon = find_mapping_colon(part).ok_or_else(|| "did not find expected ':'".to_string())?;
                let k = parse_scalar_token(part[..colon].trim());
                let v = parse_inline(part[colon + 1..].trim())?;
                let mut replaced = false;
                for pair in pairs.iter_mut() {
                    if pair.0 == k { pair.1 = v.clone(); replaced = true; break; }
                }
                if !replaced { pairs.push((k, v)); }
            }
        }
        return Ok(Yaml::Hash(pairs));
    }
    if t.starts_with('[') {
        if !t.ends_with(']') {
            return Err("while parsing a flow sequence, expected ',' or ']'".to_string());
        }
        let inner = &t[1..t.len() - 1];
        let mut items = Vec::new();
        if !inner.trim().is_empty() {
            for part in split_flow(inner) {
                items.push(parse_inline(part.trim())?);
            }
        }
        return Ok(Yaml::Array(items));
    }
    Ok(parse_scalar_token(t))
}

fn split_flow(inner: &str) -> Vec<String> {
    let mut parts = Vec::new();
    let mut depth = 0i32;
    let mut in_single = false;
    let mut in_double = false;
    let mut escaped = false;
    let mut cur = String::new();
    for c in inner.chars() {
        if in_double {
            cur.push(c);
            if escaped { escaped = false; } else if c == '\\' { escaped = true; } else if c == '"' { in_double = false; }
            continue;
        }
        if in_single {
            cur.push(c);
            if c == '\'' { in_single = false; }
            continue;
        }
        match c {
            '"' => { in_double = true; cur.push(c); }
            '\'' => { in_single = true; cur.push(c); }
            '{' | '[' => { depth += 1; cur.push(c); }
            '}' | ']' => { depth -= 1; cur.push(c); }
            ',' if depth == 0 => { parts.push(cur.clone()); cur.clear(); }
            _ => cur.push(c),
        }
    }
    if !cur.is_empty() || !parts.is_empty() {
        parts.push(cur);
    }
    parts
}

fn parse_scalar_token(t0: &str) -> Yaml {
    let t = t0.trim();
    if t.starts_with('"') {
        return Yaml::String(parse_double_quoted(t));
    }
    if t.starts_with('\'') {
        return Yaml::String(parse_single_quoted(t));
    }
    match t {
        "" | "~" | "null" | "Null" | "NULL" => return Yaml::Null,
        "true" | "True" | "TRUE" => return Yaml::Boolean(true),
        "false" | "False" | "FALSE" => return Yaml::Boolean(false),
        ".inf" | ".Inf" | ".INF" | "+.inf" | "+.Inf" | "+.INF" => return Yaml::Real(t.to_string()),
        "-.inf" | "-.Inf" | "-.INF" => return Yaml::Real(t.to_string()),
        ".nan" | ".Nan" | ".NAN" => return Yaml::Real(t.to_string()),
        _ => {}
    }
    // Integer forms recognised by yaml-rust.
    if let Some(v) = parse_yaml_integer(t) {
        return Yaml::Integer(v);
    }
    if is_yaml_float(t) {
        return Yaml::Real(t.to_string());
    }
    Yaml::String(t.to_string())
}

fn parse_yaml_integer(t: &str) -> Option<i64> {
    let (sign, rest) = if let Some(r) = t.strip_prefix('-') {
        (-1i64, r)
    } else if let Some(r) = t.strip_prefix('+') {
        (1i64, r)
    } else {
        (1i64, t)
    };
    if let Some(hex) = rest.strip_prefix("0x") {
        if hex.is_empty() || !hex.chars().all(|c| c.is_ascii_hexdigit()) { return None; }
        return i64::from_str_radix(hex, 16).ok().map(|v| sign * v);
    }
    if let Some(oct) = rest.strip_prefix("0o") {
        if oct.is_empty() || !oct.chars().all(|c| ('0'..='7').contains(&c)) { return None; }
        return i64::from_str_radix(oct, 8).ok().map(|v| sign * v);
    }
    if !rest.is_empty() && rest.chars().all(|c| c.is_ascii_digit()) {
        return t.parse::<i64>().ok();
    }
    None
}

fn is_yaml_float(t: &str) -> bool {
    // yaml-rust tries a float parse for strings that look numeric.
    let s = t.strip_prefix(['-', '+']).unwrap_or(t);
    if s.is_empty() { return false; }
    let looks = s.chars().next().map(|c| c.is_ascii_digit() || c == '.').unwrap_or(false);
    if !looks { return false; }
    // Must contain a '.' or exponent marker to be treated as float rather
    // than a plain string of digits with trailing junk.
    if !(s.contains('.') || s.contains('e') || s.contains('E')) { return false; }
    t.parse::<f64>().is_ok()
}

fn parse_double_quoted(t: &str) -> String {
    let mut out = String::new();
    let mut chars = t.chars();
    chars.next(); // opening quote
    let mut iter = chars.peekable();
    while let Some(c) = iter.next() {
        match c {
            '"' => break,
            '\\' => {
                match iter.next() {
                    Some('n') => out.push('\n'),
                    Some('t') => out.push('\t'),
                    Some('r') => out.push('\r'),
                    Some('0') => out.push('\0'),
                    Some('\\') => out.push('\\'),
                    Some('"') => out.push('"'),
                    Some('\'') => out.push('\''),
                    Some(other) => { out.push('\\'); out.push(other); }
                    None => out.push('\\'),
                }
            }
            other => out.push(other),
        }
    }
    out
}

fn parse_single_quoted(t: &str) -> String {
    let mut out = String::new();
    let mut chars = t.chars();
    chars.next();
    let mut peek = chars.peekable();
    while let Some(c) = peek.next() {
        if c == '\'' {
            if peek.peek() == Some(&'\'') {
                peek.next();
                out.push('\'');
            } else {
                break;
            }
        } else {
            out.push(c);
        }
    }
    out
}

// Re-exported for convenience in other modules.
pub fn string(s: &str) -> Yaml {
    Yaml::String(s.to_string())
}

pub fn hash(pairs: Vec<(&str, Yaml)>) -> Yaml {
    Yaml::Hash(pairs.into_iter().map(|(k, v)| (Yaml::String(k.to_string()), v)).collect())
}

pub fn empty_hash() -> Yaml {
    Yaml::Hash(Vec::new())
}

pub fn hash_map(pairs: &[(String, String)]) -> HashMap<String, String> {
    let mut m = HashMap::new();
    for (k, v) in pairs { m.insert(k.clone(), v.clone()); }
    m
}
