// ---------- colour naming ----------

pub fn color_name(upper: &str) -> String {
    let hex_part: &str = if upper.starts_with('#') {
        if upper.len() < 7 {
            panic!("got invalid hex string: {}", upper);
        }
        &upper[1..7]
    } else {
        if upper.len() < 6 {
            panic!("got invalid hex string: {}", upper);
        }
        &upper[0..6]
    };
    let parse_pair = |s: &str| -> u8 {
        match u8::from_str_radix(s, 16) {
            Ok(v) => v,
            Err(_) => panic!("got invalid hex string: {}", upper),
        }
    };
    let r = parse_pair(&hex_part[0..2]);
    let g = parse_pair(&hex_part[2..4]);
    let b = parse_pair(&hex_part[4..6]);
    // Hand-checked colours first.
    if let Some((_, name)) = KNOWN_COLOR_NAMES
        .iter()
        .find(|(hex, _)| *hex == upper)
    {
        return name.to_string();
    }
    for ((er, eg, eb), name) in EXACT_NAME_OVERRIDES.iter() {
        if (*er, *eg, *eb) == (r, g, b) {
            return name.to_string();
        }
    }
    let mut best_name: &str = "black";
    let mut best_dist: i64 = i64::MAX;
    for (name, cr, cg, cb) in COLOR_NAMES.iter() {
        let dr = r as i64 - *cr as i64;
        let dg = g as i64 - *cg as i64;
        let db = b as i64 - *cb as i64;
        let dist = dr * dr + dg * dg + db * db;
        if dist < best_dist {
            best_dist = dist;
            best_name = name;
            if dist == 0 {
                break;
            }
        }
    }
    best_name.to_string()
}

struct ColorRegistry {
    entries: Vec<(String, String)>, // (upper hex, assigned name) in order
    base_counts: Vec<(String, usize)>,
}

impl ColorRegistry {
    fn new() -> Self {
        ColorRegistry { entries: Vec::new(), base_counts: Vec::new() }
    }
    fn register(&mut self, raw: &str) -> String {
        let upper = raw.to_uppercase();
        for (hex, name) in self.entries.iter() {
            if *hex == upper {
                return name.clone();
            }
        }
        let base = color_name(&upper);
        let mut count = 0usize;
        for (b, c) in self.base_counts.iter_mut() {
            if *b == base {
                count = *c;
                *c += 1;
                break;
            }
        }
        if count == 0 && !self.base_counts.iter().any(|(b, _)| *b == base) {
            self.base_counts.push((base.clone(), 1));
        }
        let assigned = if count == 0 {
            base.clone()
        } else {
            format!("{}-{}", base, count)
        };
        self.entries.push((upper, assigned.clone()));
        assigned
    }
}

