    let bg_name = parsed.background.as_ref().map(|v| registry.register(v));
    let status_name = parsed.statusline.as_ref().map(|v| registry.register(v));

    let mut reg_ws = |ws: &WorkspaceRaw, registry: &mut ColorRegistry| -> (Option<String>, Option<String>, Option<String>) {
        let b = ws.border.as_ref().map(|v| registry.register(v));
        let bg = ws.background.as_ref().map(|v| registry.register(v));
        let t = ws.text.as_ref().map(|v| registry.register(v));
        (b, bg, t)
    };
    let fw = reg_ws(&parsed.focused_workspace, &mut registry);
    let iw = reg_ws(&parsed.inactive_workspace, &mut registry);
    let _ = &iw;
    let uw = reg_ws(&parsed.urgent_workspace, &mut registry);

    let mut reg_win = |w: &WindowRaw, registry: &mut ColorRegistry| -> (Option<String>, Option<String>, Option<String>, Option<String>) {
        let b = w.border.as_ref().map(|v| registry.register(v));
        let bg = w.background.as_ref().map(|v| registry.register(v));
        let t = w.text.as_ref().map(|v| registry.register(v));
        let i = w.indicator.as_ref().map(|v| registry.register(v));
        (b, bg, t, i)
    };
    let focused = reg_win(&parsed.focused, &mut registry);
    let focused_inactive = reg_win(&parsed.focused_inactive, &mut registry);
    let unfocused = reg_win(&parsed.unfocused, &mut registry);
    let urgent = reg_win(&parsed.urgent, &mut registry);

    // Build the YAML document.
    let mut colors_pairs: Vec<(Yaml, Yaml)> = Vec::new();
    for (hex, name) in registry.entries.iter() {
        colors_pairs.push((yaml::string(name), yaml::string(hex)));
    }

    let mut window_pairs: Vec<(Yaml, Yaml)> = Vec::new();
    let wins = [
        ("focused", &parsed.focused, &focused),
        ("focused_inactive", &parsed.focused_inactive, &focused_inactive),
        ("unfocused", &parsed.unfocused, &unfocused),
        ("urgent", &parsed.urgent, &urgent),
    ];
    for (name, raw, named) in wins.iter() {
        if raw.present {
            let mut pairs: Vec<(Yaml, Yaml)> = Vec::new();
            if let Some(v) = &named.0 { pairs.push((yaml::string("border"), yaml::string(v))); }
            if let Some(v) = &named.1 { pairs.push((yaml::string("background"), yaml::string(v))); }
            if let Some(v) = &named.2 { pairs.push((yaml::string("text"), yaml::string(v))); }
            if let Some(v) = &named.3 { pairs.push((yaml::string("indicator"), yaml::string(v))); }
            window_pairs.push((yaml::string(name), Yaml::Hash(pairs)));
        }
    }

    let mut bar_pairs: Vec<(Yaml, Yaml)> = Vec::new();
    if let Some(v) = &bg_name { bar_pairs.push((yaml::string("background"), yaml::string(v))); }
    if let Some(v) = &status_name { bar_pairs.push((yaml::string("statusline"), yaml::string(v))); }
    if let Some(v) = &sep_name { bar_pairs.push((yaml::string("separator"), yaml::string(v))); }
    if parsed.focused_workspace.present {
        let mut pairs: Vec<(Yaml, Yaml)> = Vec::new();
        if let Some(v) = &fw.0 { pairs.push((yaml::string("border"), yaml::string(v))); }
        if let Some(v) = &fw.1 { pairs.push((yaml::string("background"), yaml::string(v))); }
        if let Some(v) = &fw.2 { pairs.push((yaml::string("text"), yaml::string(v))); }
        bar_pairs.push((yaml::string("focused_workspace"), Yaml::Hash(pairs)));
    }
    if parsed.urgent_workspace.present {
        let mut pairs: Vec<(Yaml, Yaml)> = Vec::new();
        if let Some(v) = &uw.0 { pairs.push((yaml::string("border"), yaml::string(v))); }
        if let Some(v) = &uw.1 { pairs.push((yaml::string("background"), yaml::string(v))); }
        if let Some(v) = &uw.2 { pairs.push((yaml::string("text"), yaml::string(v))); }
        bar_pairs.push((yaml::string("urgent_workspace"), Yaml::Hash(pairs)));
    }

    let root = yaml::hash(vec![
        (
            "meta",
            yaml::hash(vec![(
                "description",
                yaml::string("AUTOMATICALLY GENERATED THEME"),
            )]),
        ),
        ("colors", Yaml::Hash(colors_pairs)),
        ("window_colors", Yaml::Hash(window_pairs)),
        ("bar_colors", Yaml::Hash(bar_pairs)),
    ]);
    emit_yaml_document(&root)
}

// ---------- YAML emission (compatible with the yaml-rust emitter for the
// shapes produced here) ----------

pub fn emit_yaml_document(root: &Yaml) -> String {
    let mut out = String::new();
    out.push_str("---\n");
    emit_mapping(root, 0, &mut out);
    out
}

fn emit_mapping(node: &Yaml, indent: usize, out: &mut String) {
    if let Yaml::Hash(pairs) = node {
        for (k, v) in pairs {
            let key = match k {
                Yaml::String(s) => format_yaml_string(s),
                _ => format_yaml_string(&format!("{:?}", k)),
            };
            match v {
                Yaml::Hash(inner) if !inner.is_empty() => {
                    out.push_str(&format!("{}{}:\n", " ".repeat(indent), key));
                    emit_mapping(v, indent + 2, out);
                }
                Yaml::Hash(_) => {
                    out.push_str(&format!("{}{}: {{}}\n", " ".repeat(indent), key));
                }
                Yaml::String(s) => {
                    out.push_str(&format!("{}{}: {}\n", " ".repeat(indent), key, format_yaml_string(s)));
                }
                Yaml::Null => {
                    out.push_str(&format!("{}{}: ~\n", " ".repeat(indent), key));
                }
                Yaml::Boolean(b) => {
                    out.push_str(&format!("{}{}: {}\n", " ".repeat(indent), key, b));
                }
                Yaml::Integer(i) => {
                    out.push_str(&format!("{}{}: {}\n", " ".repeat(indent), key, i));
                }
                Yaml::Real(r) => {
                    out.push_str(&format!("{}{}: {}\n", " ".repeat(indent), key, r));
                }
                _ => {
                    out.push_str(&format!("{}{}: {:?}\n", " ".repeat(indent), key, v));
                }
            }
        }
    }
}

pub fn format_yaml_string(s: &str) -> String {
    if need_quotes(s) {
        let mut out = String::new();
        out.push('"');
        for c in s.chars() {
            match c {
                '"' => out.push_str("\\\""),
                '\\' => out.push_str("\\\\"),
                _ => out.push(c),
            }
        }
        out.push('"');
        out
    } else {
        s.to_string()
    }
}

fn need_quotes(s: &str) -> bool {
    if s.is_empty() {
        return true;
    }
    // Strings that would be read back as a non-string scalar.
    match s {
        "~" | "null" | "Null" | "NULL" | "true" | "True" | "TRUE" | "false" | "False" | "FALSE" => return true,
        _ => {}
    }
    if s.parse::<i64>().is_ok() || s.parse::<f64>().is_ok() {
        // `123456`, `12.5`, etc.
        if s.chars().all(|c| c.is_ascii_digit() || c == '.' || c == '-' || c == '+' || c == 'e' || c == 'E') {
            return true;
        }
    }
    let first = s.chars().next().unwrap();
    if "#&*!|>'\"%@`".contains(first) {
        return true;
    }
    if s.starts_with("- ") || s.starts_with("? ") || s.starts_with(": ") || s == "-" || s == "?" || s == ":" {
        return true;
    }
    if s.trim() != s {
        return true;
    }
    for c in s.chars() {
        if c == '\n' || c == '\r' || c == '\t' {
            return true;
        }
        if (c as u32) < 0x20 {
            return true;
        }
    }
    if s.contains(": ") || s.contains(" #") || s.ends_with(':') || s.contains('"') || s.contains('\\') {
        return true;
    }
    false
}
