{"command":"cat > src/writer.rs <<'RS'
use crate::theme::resolve_color;
use crate::yaml::Yaml;
use std::fs::File;
use std::io::{self, BufRead, BufReader, Write};

const WINDOW_CLASSES: [&str; 4] = ["focused", "focused_inactive", "unfocused", "urgent"];
const BAR_WORKSPACES: [&str; 4] = [
    "focused_workspace",
    "active_workspace",
    "inactive_workspace",
    "urgent_workspace",
];
const BAR_SINGLES: [&str; 3] = ["separator", "background", "statusline"];

fn split_indent(line: &str) -> (&str, &str) {
    let idx = line.find(|c: char| !c.is_whitespace()).unwrap_or(line.len());
    (&line[..idx], &line[idx..])
}

fn first_token(trimmed: &str) -> &str {
    trimmed.split(' ').next().unwrap_or("")
}

fn tokens_of(trimmed: &str) -> Vec<&str> {
    trimmed.split(' ').filter(|s| !s.is_empty()).collect()
}

pub struct ConfigWriter {
    theme: Yaml,
    out: Box<dyn Write>,
    in_bar: bool,
    in_colors: bool,
    bar_has_colors: bool,
    seen_clients: [bool; 4],
    seen_bar: [bool; 7], // separator, background, statusline, 4 workspaces
    seen_sep_idx: (),
}

impl ConfigWriter {
    pub fn new(theme: Yaml, out: Box<dyn Write>) -> Self {
        ConfigWriter {
            theme,
            out,
            in_bar: false,
            in_colors: false,
            bar_has_colors: false,
            seen_clients: [false; 4],
            seen_bar: [false; 7],
            seen_sep_idx: (),
        }
    }

    fn write_str(&mut self, s: &str) {
        self.out.write_all(s.as_bytes()).unwrap();
    }

    fn bar_single_idx(name: &str) -> Option<usize> {
        BAR_SINGLES.iter().position(|n| *n == name)
    }
    fn bar_workspace_idx(name: &str) -> Option<usize> {
        BAR_WORKSPACES.iter().position(|n| *n == name).map(|i| 3 + i)
    }
    fn bar_prop_idx(name: &str) -> Option<usize> {
        Self::bar_single_idx(name).or_else(|| Self::bar_workspace_idx(name))
    }

    fn theme_window(&self, class: &str) -> Yaml {
        self.theme.get("window_colors").get(class)
    }
    fn theme_bar(&self, prop: &str) -> Yaml {
        self.theme.get("bar_colors").get(prop)
    }
    fn field_str(theme_node: &Yaml, field: &str) -> Option<String> {
        theme_node.get(field).as_str().map(|s| s.to_string())
    }

    fn resolved_field(&self, node: &Yaml, field: &str) -> Option<String> {
        Self::field_str(node, field).map(|raw| resolve_color(&self.theme, &raw))
    }

    // ----- generation of lines from the theme alone -----
    fn generated_bar_lines(&self, indent: &str, only_missing: bool) -> Vec<String> {
        // Access first: this is where the original unwraps the bar hash.
        let bar_hash = self.theme.get("bar_colors");
        let bar_pairs = bar_hash.as_hash().unwrap();
        let _ = bar_pairs;
        let mut lines = Vec::new();
        // Singles in canonical order.
        for (i, name) in BAR_SINGLES.iter().enumerate() {
            if only_missing && self.seen_bar[i] {
                continue;
            }
            if let Some(raw) = self.theme_bar(name).as_str() {
                let v = resolve_color(&self.theme, raw);
                lines.push(format!("{}{} {}\n", indent, name, v));
            }
        }
        for (j, name) in BAR_WORKSPACES.iter().enumerate() {
            let idx = 3 + j;
            if only_missing && self.seen_bar[idx] {
                continue;
            }
            let node = self.theme_bar(name);
            if node.as_hash().is_none() {
                continue;
            }
            let border = self.resolved_field(&node, "border");
            let background = self.resolved_field(&node, "background");
            let text = self.resolved_field(&node, "text");
            if let (Some(b), Some(bg), Some(t)) = (border, background, text) {
                let mut line = format!("{}{} {} {} {} ", indent, name, b, bg, t);
                if let Some(ind) = self.resolved_field(&node, "indicator") {
                    line.push_str(&format!(" {}", ind));
                }
                line.push('\n');
                lines.push(line);
            }
        }
        lines
    }

    fn insert_missing_bar_colors(&mut self, closing_indent: &str) {
        let indent = format!("{}{}", closing_indent, closing_indent);
        let lines = self.generated_bar_lines(&indent, true);
        for line in lines {
            self.write_str(&line);
        }
    }

    fn insert_whole_bar_colors(&mut self) {
        let lines = self.generated_bar_lines("    ", false);
        self.write_str("  colors {\n");
        for line in lines {
            self.write_str(&line);
        }
        self.write_str("  }\n");
    }

    fn append_missing_clients(&mut self) {
        if self.seen_clients.iter().all(|s| *s) {
            return;
        }
        // Access first (original unwraps here).
        let wc = self.theme.get("window_colors");
        let _pairs = wc.as_hash().unwrap();
        for (i, class) in WINDOW_CLASSES.iter().enumerate() {
            if self.seen_clients[i] {
                continue;
            }
            let node = self.theme_window(class);
            if node.as_hash().is_none() {
                continue;
            }
            let border = self.resolved_field(&node, "border").unwrap_or_else(|| "#000000".to_string());
            let background = self.resolved_field(&node, "background").unwrap_or_else(|| "#000000".to_string());
            let text = self.resolved_field(&node, "text").unwrap_or_else(|| "#000000".to_string());
            let mut line = format!("client.{} {} {} {}", class, border, background, text);
            if let Some(ind) = self.resolved_field(&node, "indicator") {
                line.push_str(&format!(" {}", ind));
            }
            line.push('\n');
            self.write_str(&line);
        }
    }

    // ----- per-line processing -----
    fn process_client_line(&mut self, line: &str, class_idx: usize) {
        let (indent, trimmed) = split_indent(line);
        let class = WINDOW_CLASSES[class_idx];
        let node = self.theme_window(class);
        if node.as_hash().is_none() {
            self.write_str(line);
            self.write_str("\n");
            return;
        }
        let toks = tokens_of(trimmed);
        self.write_str(indent);
        self.write_str(&format!("client.{} ", class));
        // border (required)
        let border = match self.resolved_field(&node, "border") {
            Some(v) => v,
            None => toks.get(1).unwrap().to_string(),
        };
        self.write_str(&format!("{} ", border));
        // background (required)
        let background = match self.resolved_field(&node, "background") {
            Some(v) => v,
            None => toks.get(2).unwrap().to_string(),
        };
        self.write_str(&format!("{} ", background));
        // text (optional)
        let text_opt = match self.resolved_field(&node, "text") {
            Some(v) => Some(v),
            None => toks.get(3).map(|s| s.to_string()),
        };
        if let Some(text) = text_opt {
            self.write_str(&format!("{} ", text));
            let indicator = match self.resolved_field(&node, "indicator") {
                Some(v) => v,
                None => toks.get(4).map(|s| s.to_string()).unwrap_or_default(),
            };
            self.write_str(&indicator);
        }
        self.write_str("\n");
    }

    fn process_bar_single(&mut self, line: &str, name: &str) {
        let (indent, trimmed) = split_indent(line);
        let toks = tokens_of(trimmed);
        self.write_str(indent);
        self.write_str(&format!("{} ", name));
        let value = match self.theme_bar(name).as_str() {
            Some(raw) => resolve_color(&self.theme, raw),
            None => toks.get(1).unwrap().to_string(),
        };
        self.write_str(&value);
        self.write_str("\n");
    }

    fn process_bar_workspace(&mut self, line: &str, name: &str) {
        let node = self.theme_bar(name);
        if node.as_hash().is_none() {
            self.write_str(line);
            self.write_str("\n");
            return;
        }
        let (indent, trimmed) = split_indent(line);
        let toks = tokens_of(trimmed);
        self.write_str(indent);
        self.write_str(&format!("{} ", name));
        let border = match self.resolved_field(&node, "border") {
            Some(v) => v,
            None => toks.get(1).unwrap().to_string(),
        };
        self.write_str(&format!("{} ", border));
        let background = match self.resolved_field(&node, "background") {
            Some(v) => v,
            None => toks.get(2).unwrap().to_string(),
        };
        self.write_str(&format!("{} ", background));
        let text = match self.resolved_field(&node, "text") {
            Some(v) => v,
            None => toks.get(3).unwrap().to_string(),
        };
        self.write_str(&format!("{} ", text));
        let indicator = match self.resolved_field(&node, "indicator") {
            Some(v) => v,
            None => toks.get(3).map(|s| s.to_string()).unwrap_or_default(),
        };
        self.write_str(&indicator);
        self.write_str("\n");
    }

    fn process_line(&mut self, line: &str) {
        let (indent, trimmed) = split_indent(line);
        let token = first_token(trimmed).to_string();
        let _ = self.seen_sep_idx;
        if self.in_colors {
            if token == "}" {
                self.insert_missing_bar_colors(indent);
                self.write_str(line);
                self.write_str("\n");
                self.in_colors = false;
                return;
            }
            if let Some(idx) = Self::bar_prop_idx(&token) {
                self.seen_bar[idx] = true;
                if Self::bar_single_idx(&token).is_some() {
                    self.process_bar_single(line, &token.clone());
                } else {
                    self.process_bar_workspace(line, &token.clone());
                }
                return;
            }
            if trimmed.is_empty() || trimmed.starts_with('#') {
                self.write_str(line);
                self.write_str("\n");
                return;
            }
            // Unrecognised lines inside a colours block are dropped.
            return;
        }

        // Window colours are recognised anywhere outside a colours block.
        let client_names = [
            "client.focused",
            "client.focused_inactive",
            "client.unfocused",
            "client.urgent",
        ];
        if let Some(ci) = client_names.iter().position(|n| *n == token) {
            self.seen_clients[ci] = true;
            self.process_client_line(line, ci);
            return;
        }

        if self.in_bar {
            if token == "colors" {
                self.in_colors = true;
                self.bar_has_colors = true;
                self.seen_bar = [false; 7];
                self.write_str(line);
                self.write_str("\n");
                return;
            }
            if token == "}" {
                if !self.bar_has_colors {
                    self.insert_whole_bar_colors();
                }
                self.write_str(line);
                self.write_str("\n");
                self.in_bar = false;
                return;
            }
            self.write_str(line);
            self.write_str("\n");
            return;
        }

        if token == "bar" {
            self.in_bar = true;
            self.bar_has_colors = false;
            self.write_str(line);
            self.write_str("\n");
            return;
        }

        self.write_str(line);
        self.write_str("\n");
    }

    pub fn run(&mut self, config_path: &str) {
        let in_file = File::open(config_path).unwrap();
        let reader = BufReader::new(in_file);
        for line_res in reader.lines() {
            let line = line_res.unwrap();
            self.process_line(&line);
        }
        self.append_missing_clients();
        // Make sure a stdout writer sees everything before any later exit.
        let _ = self.out.flush();
    }
}

pub fn write_to_stdout(config_path: &str, theme: Yaml) {
    let out: Box<dyn Write> = Box::new(io::stdout());
    let mut writer = ConfigWriter::new(theme, out);
    writer.run(config_path);
}

pub fn write_to_file(config_path: &str, theme: Yaml, target: &std::path::Path) {
    // The input is opened in `run`; to mirror the original ordering (the
    // temporary output file is not created when the input cannot be
    // opened) we open the input once here before creating the file.
    // `run` will open it again.
    {
        let probe = File::open(config_path).unwrap();
        drop(probe);
    }
    let file = File::create(target).unwrap();
    let mut writer = ConfigWriter::new(theme, Box::new(file));
    writer.run(config_path);
}
RS
