{"command":"cat > src/cli.rs <<'RS'
use std::env;
use std::ffi::{OsStr, OsString};
use std::process;

#[derive(Clone, Debug)]
pub struct Args {
    pub list_all: bool,
    pub reload: bool,
    pub save: bool,
    pub config: Option<OsString>,
    pub output: Option<OsString>,
    pub to_theme_present: bool,
    pub to_theme: OsString,
    pub theme: Option<OsString>,
    pub bin_name: String,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum ArgKind {
    Flag,
    Option,
}

#[derive(Clone, Copy)]
struct Def {
    id: &'static str,
    long: &'static str,
    short: Option<char>,
    kind: ArgKind,
}

const DEFS: &[Def] = &[
    Def { id: "config", long: "config", short: Some('c'), kind: ArgKind::Option },
    Def { id: "help", long: "help", short: Some('h'), kind: ArgKind::Flag },
    Def { id: "list-all", long: "list-all", short: Some('l'), kind: ArgKind::Flag },
    Def { id: "output", long: "output", short: Some('o'), kind: ArgKind::Option },
    Def { id: "reload", long: "reload", short: Some('r'), kind: ArgKind::Flag },
    Def { id: "save", long: "save", short: Some('s'), kind: ArgKind::Flag },
    Def { id: "to-theme", long: "to-theme", short: Some('t'), kind: ArgKind::Option },
    Def { id: "version", long: "version", short: Some('V'), kind: ArgKind::Flag },
];

fn def_by_long(long: &str) -> Option<&'static Def> {
    DEFS.iter().find(|d| d.long == long)
}
fn def_by_short(c: char) -> Option<&'static Def> {
    DEFS.iter().find(|d| d.short == Some(c))
}
fn def_by_id(id: &str) -> &'static Def {
    DEFS.iter().find(|d| d.id == id).unwrap()
}

fn usage_of(d: &Def) -> String {
    match d.kind {
        ArgKind::Flag => format!("--{}", d.long),
        ArgKind::Option => format!("--{} <file>", d.long),
    }
}

fn error_arg_display(d: &Def) -> String {
    // The first line of missing/duplicate errors.
    usage_of(d)
}

pub fn bin_name() -> String {
    let mut args = env::args_os();
    if let Some(a0) = args.next() {
        if !a0.is_empty() {
            let path = std::path::Path::new(&a0);
            if let Some(fname) = path.file_name() {
                let s = fname.to_string_lossy().to_string();
                if !s.is_empty() {
                    return s;
                }
            }
            let s = a0.to_string_lossy().to_string();
            if !s.is_empty() {
                return s;
            }
        }
    }
    "i3-style".to_string()
}

pub fn print_help(bin: &str) -> ! {
    print!(
        "i3-style 1.0\nMake your i3 config a bit more stylish\n\nUSAGE:\n    {} [FLAGS] [OPTIONS] [theme]\n\nFLAGS:\n    -h, --help        Prints help information\n    -l, --list-all    Print a list of all available themes\n    -r, --reload      Apply the theme by reloading the config\n    -s, --save        Set the output file to the path of the input file\n    -V, --version     Prints version information\n\nOPTIONS:\n    -c, --config <file>      The config file the theme should be applied to. Defaults to the default i3 location.\n    -o, --output <file>      Apply the theme, attempt to validate the result, and write it to <file>\n    -t, --to-theme <file>    Prints an i3-style theme based on the given config suitable for sharing with others\n                             [default: ]\n\nARGS:\n    <theme>    The theme to use\n",
        bin
    );
    let _ = std::io::Write::flush(&mut std::io::stdout());
    process::exit(0);
}

pub fn print_version() -> ! {
    println!("i3-style 1.0");
    process::exit(0);
}

fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a.is_empty() && b.is_empty() { return 1.0; }
    if a.is_empty() || b.is_empty() { return 0.0; }
    let match_dist = std::cmp::max(a.len(), b.len()) / 2;
    let mut a_matched = vec![false; a.len()];
    let mut b_matched = vec![false; b.len()];
    let mut matches = 0usize;
    for i in 0..a.len() {
        let start = if i > match_dist { i - match_dist } else { 0 };
        let end = std::cmp::min(i + match_dist + 1, b.len());
        for j in start..end {
            if !b_matched[j] && a[i] == b[j] {
                a_matched[i] = true;
                b_matched[j] = true;
                matches += 1;
                break;
            }
        }
    }
    if matches == 0 { return 0.0; }
    let mut transpositions = 0usize;
    let mut j = 0usize;
    for i in 0..a.len() {
        if a_matched[i] {
            while !b_matched[j] { j += 1; }
            if a[i] != b[j] { transpositions += 1; }
            j += 1;
        }
    }
    let m = matches as f64;
    (m / a.len() as f64 + m / b.len() as f64 + (m - (transpositions / 2) as f64) / m) / 3.0
}

fn jaro_winkler(a: &str, b: &str) -> f64 {
    let j = jaro(a, b);
    if j > 0.7 {
        let prefix = a.chars().zip(b.chars()).take(4).take_while(|(x, y)| x == y).count();
        j + (prefix as f64 * 0.1 * (1.0 - j))
    } else {
        j
    }
}

fn did_you_mean(v: &str) -> Option<&'static Def> {
    let mut best: Option<(f64, &'static Def)> = None;
    for d in DEFS.iter() {
        let conf = jaro_winkler(v, d.long);
        if conf > 0.8 {
            match best {
                Some((bc, _)) if bc >= conf => {}
                _ => best = Some((conf, d)),
            }
        }
    }
    best.map(|(_, d)| d)
}

fn sorted_usage(bin: &str, ids: &[&str]) -> String {
    let mut uniq: Vec<&str> = Vec::new();
    for id in ids {
        if !uniq.contains(id) { uniq.push(id); }
    }
    uniq.sort_by(|a, b| def_by_id(a).long.cmp(def_by_id(b).long));
    let parts: Vec<String> = uniq.iter().map(|id| usage_of(def_by_id(id))).collect();
    if parts.is_empty() {
        format!("{} [FLAGS] [OPTIONS] [theme]", bin)
    } else {
        format!("{} {}", bin, parts.join(" "))
    }
}

fn unknown_error(bin: &str, display: &str, used: &[&str], suggestion: Option<&'static Def>) -> ! {
    let mut msg = String::new();
    msg.push_str(&format!(
        "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n",
        display
    ));
    if let Some(d) = suggestion {
        msg.push_str(&format!(
            "\tDid you mean \u{1b}[32m--\u{1b}[0m\u{1b}[32m{}\u{1b}[0m?\n",
            d.long
        ));
    }
    let usage = if used.is_empty() && suggestion.is_none() {
        format!("{} [FLAGS] [OPTIONS] [theme]", bin)
    } else {
        let mut ids: Vec<&str> = used.to_vec();
        if let Some(d) = suggestion { ids.push(d.id); }
        sorted_usage(bin, &ids)
    };
    msg.push_str(&format!("\nUSAGE:\n    {}\n\nFor more information try --help\n", usage));
    eprint!("{}", msg);
    process::exit(1);
}

fn value_error(bin: &str, kind: &str, d: &Def, used: &[&str]) -> ! {
    // kind: "missing" or "duplicate"
    let mut ids: Vec<&str> = used.to_vec();
    if !ids.contains(&"to-theme") { ids.push("to-theme"); }
    let usage = sorted_usage(bin, &ids);
    if kind == "missing" {
        eprintln!(
            "error: The argument '{}' requires a value but none was supplied\n\nUSAGE:\n    {}\n\nFor more information try --help",
            error_arg_display(d), usage
        );
    } else {
        eprintln!(
            "error: The argument '{}' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    {}\n\nFor more information try --help",
            error_arg_display(d), usage
        );
    }
    process::exit(1);
}

fn os_to_string(v: &OsStr) -> String {
    match v.to_str() {
        Some(s) => s.to_string(),
        None => panic!("unexpected invalid UTF-8 code point"),
    }
}

fn is_flag_like(v: &OsString) -> bool {
    let s = v.to_string_lossy();
    s.len() > 1 && s.starts_with('-')
}

#[derive(Clone)]
enum Deferred {
    Missing(&'static Def, usize),
    Duplicate(&'static Def, usize),
}

pub fn parse() -> Args {
    let bin = bin_name();
    let argv: Vec<OsString> = env::args_os().skip(1).collect();
    let mut out = Args {
        list_all: false,
        reload: false,
        save: false,
        config: None,
        output: None,
        to_theme_present: false,
        to_theme: OsString::new(),
        theme: None,
        bin_name: bin.clone(),
    };
    let mut used: Vec<&'static str> = Vec::new();
    let mut counts: Vec<(&'static str, usize)> = Vec::new();
    let mut deferred: Option<Deferred> = None;
    let mut seq = 0usize;
    let mut after_dashdash = false;

    let mut mark_used = |d: &'static Def, used: &mut Vec<&'static str>, counts: &mut Vec<(&'static str, usize)>, deferred: &mut Option<Deferred>, seq: &mut usize| {
        if !used.contains(&d.id) { used.push(d.id); }
        let mut cnt = 1usize;
        for e in counts.iter_mut() {
            if e.0 == d.id { e.1 += 1; cnt = e.1; break; }
        }
        if cnt == 1 && !counts.iter().any(|e| e.0 == d.id) {
            counts.push((d.id, 1));
        }
        if cnt > 1 {
            *seq += 1;
            *deferred = Some(Deferred::Duplicate(d, *seq));
        }
    };

    let mut i = 0usize;
    while i < argv.len() {
        let arg = &argv[i];
        if after_dashdash {
            // positional
            if out.theme.is_some() {
                unknown_error(&bin, &os_to_string(arg), &used, None);
            }
            out.theme = Some(arg.clone());
            i += 1;
            continue;
        }
        let bytes_lossy = arg.to_string_lossy().to_string();
        if bytes_lossy == "--" {
            after_dashdash = true;
            i += 1;
            continue;
        }
        // Long arguments
        if bytes_lossy.starts_with("--") && arg.to_str().map(|s| s.len() > 2).unwrap_or(false) {
            let body = &os_to_string(arg)[2..];
            let (name_part, attached) = match body.find('=') {
                Some(p) => (&body[..p], Some(body[p + 1..].to_string())),
                None => (body, None),
            };
            if let Some(d) = def_by_long(name_part) {
                if d.id == "help" {
                    print_help(&bin);
                }
                if d.id == "version" {
                    print_version();
                }
                match d.kind {
                    ArgKind::Flag => {
                        mark_used(d, &mut used, &mut counts, &mut deferred, &mut seq);
                        match d.id {
                            "list-all" => out.list_all = true,
                            "reload" => out.reload = true,
                            "save" => out.save = true,
                            _ => {}
                        }
                        i += 1;
                    }
                    ArgKind::Option => {
                        mark_used(d, &mut used, &mut counts, &mut deferred, &mut seq);
                        if d.id == "to-theme" { out.to_theme_present = true; }
                        let mut value: Option<OsString> = attached.map(OsString::from);
                        if value.is_none() {
                            // Look ahead
                            if i + 1 < argv.len() && !is_flag_like(&argv[i + 1]) {
                                value = Some(argv[i + 1].clone());
                                i += 1;
                            } else if d.id == "to-theme" {
                                value = None;
                            } else {
                                seq += 1;
                                // Record missing unless a duplicate for the
                                // same argument is already the deferred error.
                                let keep = matches!(&deferred, Some(Deferred::Duplicate(dd, _)) if dd.id == d.id);
                                if !keep {
                                    deferred = Some(Deferred::Missing(d, seq));
                                }
                                value = None;
                            }
                        }
                        if let Some(v) = value {
                            match d.id {
                                "config" => out.config = Some(v),
                                "output" => out.output = Some(v),
                                "to-theme" => { out.to_theme = v; out.to_theme_present = true; }
                                _ => {}
                            }
                        }
                        i += 1;
                    }
                }
            } else {
                let display = format!("--{}", name_part);
                let suggestion = did_you_mean(name_part);
                unknown_error(&bin, &display, &used, suggestion);
            }
            continue;
        }
        // Short arguments
        if bytes_lossy.starts_with('-') && bytes_lossy.len() > 1 && !bytes_lossy.starts_with("--") {
            // Must be valid UTF-8 for clap to parse the cluster; a lone
            // invalid byte sequence here makes clap panic.
            let s = os_to_string(arg);
            let chars: Vec<char> = s[1..].chars().collect();
            let mut j = 0usize;
            let mut consumed_next = false;
            while j < chars.len() {
                let c = chars[j];
                if let Some(d) = def_by_short(c) {
                    if d.id == "help" { print_help(&bin); }
                    if d.id == "version" { print_version(); }
                    match d.kind {
                        ArgKind::Flag => {
                            mark_used(d, &mut used, &mut counts, &mut deferred, &mut seq);
                            match d.id {
                                "list-all" => out.list_all = true,
                                "reload" => out.reload = true,
                                "save" => out.save = true,
                                _ => {}
                            }
                            j += 1;
                        }
                        ArgKind::Option => {
                            mark_used(d, &mut used, &mut counts, &mut deferred, &mut seq);
                            if d.id == "to-theme" { out.to_theme_present = true; }
                            // Remaining characters are the value.
                            let rest: String = chars[j + 1..].iter().collect();
                            let mut value: Option<OsString> = None;
                            if !rest.is_empty() {
                                if let Some(stripped) = rest.strip_prefix('=') {
                                    value = Some(OsString::from(stripped));
                                } else {
                                    value = Some(OsString::from(rest));
                                }
                            } else if i + 1 < argv.len() && !is_flag_like(&argv[i + 1]) {
                                value = Some(argv[i + 1].clone());
                                consumed_next = true;
                            } else if d.id == "to-theme" {
                                value = None;
                            } else {
                                seq += 1;
                                let keep = matches!(&deferred, Some(Deferred::Duplicate(dd, _)) if dd.id == d.id);
                                if !keep {
                                    deferred = Some(Deferred::Missing(d, seq));
                                }
                            }
                            if let Some(v) = value {
                                match d.id {
                                    "config" => out.config = Some(v),
                                    "output" => out.output = Some(v),
                                    "to-theme" => { out.to_theme = v; out.to_theme_present = true; }
                                    _ => {}
                                }
                            }
                            j = chars.len();
                        }
                    }
                } else {
                    unknown_error(&bin, &format!("-{}", c), &used, None);
                }
            }
            if consumed_next { i += 1; }
            i += 1;
            continue;
        }
        if bytes_lossy.starts_with("--") {
            // `--` handled above; a longer invalid-UTF8 long argument makes
            // clap panic while looking for the argument name.
            panic!("unexpected invalid UTF-8 code point");
        }
        // Positional
        if out.theme.is_some() {
            unknown_error(&bin, &os_to_string(arg), &used, None);
        }
        out.theme = Some(arg.clone());
        i += 1;
    }

    if let Some(def_err) = deferred {
        match def_err {
            Deferred::Missing(d, _) => value_error(&bin, "missing", d, &used),
            Deferred::Duplicate(d, _) => value_error(&bin, "duplicate", d, &used),
        }
    }
    out
}
RS
"}

