mod cli;
mod colornames;
mod theme;
mod writer;
mod yaml;

use std::env;
use std::ffi::OsString;
use std::fs;
use std::io::{self, Write};
use std::path::{Path, PathBuf};
use std::process::{self, Command};

fn os_string_to_string(v: &OsString) -> String {
    match v.to_str() {
        Some(s) => s.to_string(),
        None => panic!("unexpected invalid UTF-8 code point"),
    }
}

fn create_tmp_dir() -> PathBuf {
    let timestamp = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_secs();
    let dir = env::temp_dir().join("i3-style").join(timestamp.to_string());
    fs::create_dir_all(&dir).expect("Could not create temporary directory");
    dir
}

fn find_default_config() -> String {
    let home = env::var("HOME").unwrap();
    let first = format!("{}/.i3/config", home);
    if Path::new(&first).exists() {
        return first;
    }
    let second = format!("{}/.config/i3/config", home);
    if Path::new(&second).exists() {
        return second;
    }
    eprintln!("Could not find i3 config");
