    log=pathlib.Path("/tmp/i3.log").read_bytes() if pathlib.Path("/tmp/i3.log").exists() else b""
    out_files={}
    for p in sorted(pathlib.Path(cwd).rglob("*")):
        if p.is_file():
            out_files[str(p.relative_to(cwd))]=p.read_bytes()
    tmp={}
    if pathlib.Path("/tmp/i3-style").exists():
        for p in sorted(pathlib.Path("/tmp/i3-style").rglob("*")):
            if p.is_file():
                np=re.sub(r'^\d+$', 'TS', str(p.relative_to("/tmp/i3-style")).split('/')[0])
                rel='/'.join([np]+str(p.relative_to("/tmp/i3-style")).split('/')[1:])
                tmp[rel]=p.read_bytes()
    return (r.returncode, normalize(r.stdout), normalize(r.stderr), log, out_files, tmp)

total=0; failed=0
def compare(name, args, files=None, env_extra=None):
    global total, failed
    if files is None: files={"config": MINIMAL}
    total+=1
    a=run_one(ORIG,args,files=files,env_extra=env_extra)
    b=run_one(NEW,args,files=files,env_extra=env_extra)
    if a!=b:
        failed+=1
        print(f"FAIL {name} args={args} env={env_extra}")
        labels=["rc","stdout","stderr","i3log","out_files","tmp"]
        for lab,av,bv in zip(labels,a,b):
            if av!=bv:
                print(f"  {lab} orig={av!r}")
                print(f"  {lab} new ={bv!r}")
        return False
    print(f"ok {name}")
    return True

